-- mod-advanced-professions: геройские заготовки боссов.
--
-- ФАЙЛ СОБРАН ГЕНЕРАТОРОМ `tools/gen-heroic-bases.py` - правится он.
--
-- Заготовок: 1011 в блоке 183000-184999. Пропущено вещей, для
-- которых не нашлось ни одного подходящего камня: 7. Не влезло в
-- блок: 0.
--
-- ЗАМЫСЕЛ (решение владельца 2026-09-13, §2.6). Сетка основ (v32) покрывает
-- крафт и мировой дроп; у флагманских вещей - тех, что падают с боссов, -
-- своя заготовка. Босс роняет «Заготовку: Призрачный клинок»: та же модель и
-- **без единой характеристики** - ни статов, ни прока, ни гнёзд, только урон
-- в 70% от настоящего. Кузнец доводит её одним предрешённым набором.
--
-- КАЧЕСТВО ЗАГОТОВКИ - КАЧЕСТВО ЕЁ ВЕЩИ (решение владельца 2026-09-14).
-- Сначала заготовка заводилась ступенью ниже, но качество здесь - не цвет, а
-- ЧИСЛО ГНЁЗД: модуль читает его прямо из строки предмета. Ступень ниже
-- означала гнездом меньше - синяя вещь собиралась из двух камней вместо трёх,
-- эпическая из трёх вместо четырёх. Правило владельца: редкая вещь выходит из
-- редкой основы с тремя вставками, эпическая - с четырьмя. Слабость заготовки
-- держится на числах: 70% урона, пустой список статов и подпись
-- «Заготовка:» в имени.
--
-- РЕДКИЙ ОСКОЛОК в наборе остаётся там, где он есть - камень качеством выше
-- вещи попадает в неё только через своё окно (v35) и делает набор куда менее
-- угадываемым, - но обязательным быть перестал: выше эпической ступени камней
-- нет вовсе.
--
-- Способ получения у такого рецепта - `drop`: сковать заготовку нельзя, её
-- выбивают. Поэтому ячеек у неё нет вовсе и в сравнении наборов она не
-- участвует (§2.5).
--
-- Дизайн: .claude/advanced-professions/DESIGN.md §2.6.

-- --------------------------------------------------------------------------
-- 0. Повторный прогон
-- --------------------------------------------------------------------------
DELETE s FROM `ap_synergy` s
JOIN `ap_recipe` r ON r.`id` = s.`recipe_id`
WHERE r.`acquire` = 'drop' AND r.`id` BETWEEN 183000 AND 184999;

-- Снос идёт по номеру И ПО СПОСОБУ ПОЛУЧЕНИЯ: номер сам по себе не
-- доказывает, что строка наша. Однажды сюда заехала сетка основ (она брала
-- номера следом за наибольшим), и снос по одному номеру унёс её целиком.
DELETE rr FROM `ap_recipe_result` rr JOIN `ap_recipe` r ON r.`id` = rr.`recipe_id`
WHERE r.`id` BETWEEN 183000 AND 184999 AND r.`acquire` = 'drop';
DELETE ri FROM `ap_recipe_item` ri JOIN `ap_recipe` r ON r.`id` = ri.`recipe_id`
WHERE r.`id` BETWEEN 183000 AND 184999 AND r.`acquire` = 'drop';
DELETE FROM `ap_recipe`
WHERE `id` BETWEEN 183000 AND 184999 AND `acquire` = 'drop';

DELETE t FROM `item_template` t
WHERE t.`entry` BETWEEN 183000 AND 184999
  AND t.`name` LIKE 'Заготовка:%'
  AND NOT EXISTS (SELECT 1 FROM `ap_generated_item` g
                  WHERE g.`source_entry` = t.`entry`);

-- --------------------------------------------------------------------------
-- 1. Что кому принадлежит
-- --------------------------------------------------------------------------
-- Номер заготовки служит и номером её рецепта: рецептов-заготовок столько же,
-- сколько вещей, и держать для них вторую нумерацию незачем.
DROP TEMPORARY TABLE IF EXISTS `ap_hero`;
CREATE TEMPORARY TABLE `ap_hero` (
  `base`    INT UNSIGNED PRIMARY KEY,
  `prize`   INT UNSIGNED NOT NULL,
  `name`    VARCHAR(255) NOT NULL,
  `quality` TINYINT UNSIGNED NOT NULL,
  `power`   DECIMAL(6,4) NOT NULL,
  KEY (`prize`)
);

