-- --------------------------------------------------------------------------
-- 2. Сами заготовки: копия вещи, с которой снято всё
-- --------------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS `ap_blank`;
CREATE TEMPORARY TABLE `ap_blank` AS
SELECT h.`base` AS `ap_base`, h.`name` AS `ap_name`, h.`quality` AS `ap_quality`,
       h.`power` AS `ap_power`, it.*
FROM `ap_hero` h
JOIN `item_template` it ON it.`entry` = h.`prize`;

UPDATE `ap_blank` b
SET b.`entry` = b.`ap_base`,
    b.`name` = b.`ap_name`,
    b.`Quality` = b.`ap_quality`,
    -- Голые числа: заготовка бьёт слабее и не даёт НИЧЕГО сверх этого.
    b.`dmg_min1` = ROUND(b.`dmg_min1` * b.`ap_power`),
    b.`dmg_max1` = ROUND(b.`dmg_max1` * b.`ap_power`),
    b.`dmg_min2` = 0, b.`dmg_max2` = 0, b.`dmg_type2` = 0,
    b.`armor` = ROUND(b.`armor` * b.`ap_power`),
    b.`block` = 0,
    b.`stat_type1` = 0, b.`stat_value1` = 0,
    b.`stat_type2` = 0, b.`stat_value2` = 0,
    b.`stat_type3` = 0, b.`stat_value3` = 0,
    b.`stat_type4` = 0, b.`stat_value4` = 0,
    b.`stat_type5` = 0, b.`stat_value5` = 0,
    b.`stat_type6` = 0, b.`stat_value6` = 0,
    b.`stat_type7` = 0, b.`stat_value7` = 0,
    b.`stat_type8` = 0, b.`stat_value8` = 0,
    b.`stat_type9` = 0, b.`stat_value9` = 0,
    b.`stat_type10` = 0, b.`stat_value10` = 0,
    b.`spellid_1` = 0, b.`spelltrigger_1` = 0,
    b.`spellid_2` = 0, b.`spelltrigger_2` = 0,
    b.`spellid_3` = 0, b.`spellid_4` = 0, b.`spellid_5` = 0,
    -- Гнёзда вещи заготовке ни к чему: свои гнёзда ей даёт качество (§5.7).
    b.`socketColor_1` = 0, b.`socketContent_1` = 0,
    b.`socketColor_2` = 0, b.`socketContent_2` = 0,
    b.`socketColor_3` = 0, b.`socketContent_3` = 0,
    b.`socketBonus` = 0,
    -- Заготовка торгуется: она добыча, а не награда за подвиг.
    b.`bonding` = 0,
    b.`RandomProperty` = 0, b.`RandomSuffix` = 0,
    b.`startquest` = 0, b.`ScriptName` = '',
    -- ВСЁ, ЧЕМ ДОНОР БЫЛ ПРИВЯЗАН К СВОЕМУ ИСТОЧНИКУ. Список общий с v32 и
    -- с копиями призов: три блока предметов - и до сих пор три разных списка,
    -- разошедшихся молча. У заготовок оставалось 207 строк с запретом по
    -- классу, 116 уникальных и 8 в ванильном наборе.
    --
    -- Уникальность тут особенно не к месту: заготовка - это РАСХОДНИК, её
    -- кладут на верстак и тратят. `maxcount` = 1 значит, что вторая не
    -- ляжет в сумку, а босс, уронивший её повторно, потратит бросок впустую.
    b.`AllowableClass` = -1,
    b.`AllowableRace`  = -1,
    b.`RequiredSkill` = 0, b.`RequiredSkillRank` = 0,
    b.`RequiredReputationFaction` = 0, b.`RequiredReputationRank` = 0,
    b.`maxcount` = 0, b.`itemset` = 0, b.`ItemLimitCategory` = 0,
    b.`requiredhonorrank` = 0, b.`RequiredCityRank` = 0,
    b.`requiredspell` = 0, b.`RequiredDisenchantSkill` = -1,
    b.`duration` = 0,
    b.`SellPrice` = ROUND(b.`SellPrice` * b.`ap_power`),
    b.`BuyPrice` = 0;

ALTER TABLE `ap_blank` DROP COLUMN `ap_base`, DROP COLUMN `ap_name`,
                       DROP COLUMN `ap_quality`, DROP COLUMN `ap_power`;

INSERT IGNORE INTO `item_template` SELECT * FROM `ap_blank`;
DROP TEMPORARY TABLE IF EXISTS `ap_blank`;

