-- --------------------------------------------------------------------------
-- 5. Слайсы пула и заготовки копий
-- --------------------------------------------------------------------------
-- Слайс заготовки узкий: у неё один-единственный эскиз и один исход, копий
-- нужно столько, сколько таких вещей разом носят на сервере. Ковочная основа
-- держит 2048 номеров, потому что её доводят по-разному; заготовке хватает
-- 256 - и только при этом все девять сотен заготовок помещаются в блок.
SET @stride := 256;
SET @seed   := 32;
SET @block  := 1100000;

-- СЛАЙС БЕРЁТСЯ ИЗ СВОБОДНЫХ, А НЕ СЛЕДОМ ЗА ПОСЛЕДНИМ (2026-09-14).
-- Прежний счёт «наибольший занятый плюс шаг» уводил заготовки вглубь блока на
-- каждом прогоне и бросал прежние слайсы навсегда: свободный хвост кончался за
-- три-четыре перегенерации, а дальше проверка ниже роняла прогон. Теперь блок
-- нарезан на клетки по 256 номеров, занятой считается та, что пересекается с
-- ЧУЖИМ живым слайсом или содержит выданный номер, и заготовки забирают свои
-- слайсы обратно - прогон за прогоном по одним и тем же номерам.
SET SESSION cte_max_recursion_depth = 10000;

DROP TEMPORARY TABLE IF EXISTS `ap_cellseq`;
CREATE TEMPORARY TABLE `ap_cellseq` (`n` INT UNSIGNED PRIMARY KEY);
INSERT INTO `ap_cellseq`
WITH RECURSIVE `seq` (`n`) AS (
  SELECT 0 UNION ALL SELECT `n` + 1 FROM `seq` WHERE `n` < 8202
)
SELECT `n` FROM `seq`;

DROP TEMPORARY TABLE IF EXISTS `ap_free`;
CREATE TEMPORARY TABLE `ap_free` (
  `rn` INT UNSIGNED PRIMARY KEY,
  `lo` INT UNSIGNED NOT NULL
);

INSERT INTO `ap_free` (`rn`, `lo`)
SELECT ROW_NUMBER() OVER (ORDER BY `lo`), `lo`
FROM (SELECT @block + s.`n` * @stride AS `lo` FROM `ap_cellseq` s) c
WHERE NOT EXISTS (
        SELECT 1 FROM `ap_recipe_result` r
        WHERE r.`pool_lo` > 0
          AND r.`pool_lo` <= c.`lo` + @stride - 1
          AND r.`pool_hi` >= c.`lo`)
  AND NOT EXISTS (
        SELECT 1 FROM `ap_generated_item` g
        WHERE g.`entry` BETWEEN c.`lo` AND c.`lo` + @stride - 1);

DROP TEMPORARY TABLE IF EXISTS `ap_need`;
CREATE TEMPORARY TABLE `ap_need` AS
SELECT `recipe_id`, `quality`,
       ROW_NUMBER() OVER (ORDER BY `recipe_id`, `quality`) AS `rn`
FROM `ap_recipe_result`
WHERE `pool_lo` = 0 AND `result_entry` > 0;

UPDATE `ap_recipe_result` r
JOIN `ap_need` q ON q.`recipe_id` = r.`recipe_id` AND q.`quality` = r.`quality`
JOIN `ap_free` f ON f.`rn` = q.`rn`
SET r.`pool_lo` = f.`lo`,
    r.`pool_hi` = f.`lo` + @stride - 1;

-- Слайс отводится только тому, кто влез в блок: без проверки переполнение
-- прошло бы МОЛЧА, а заготовка без слайса не доводится вовсе - номер копии
-- брать неоткуда. Несуществующая таблица в имени - способ сказать это
-- голосом mysql, другого `RAISE` тут нет.
-- Имена таблиц mysql разбирает ДО выполнения, поэтому несуществующая таблица
-- внутри `IF` роняет запрос всегда, а не только в плохой ветке; отсюда
-- подготовленный запрос - разбор случается уже после выбора текста.
SET @unallocated := (SELECT COUNT(*) FROM `ap_recipe_result`
                     WHERE `pool_lo` = 0 AND `result_entry` > 0);
SET @check := IF(@unallocated = 0,
                 'SELECT ''пул нарезан целиком'' AS `проверка пула`',
                 'SELECT 1 FROM `ОШИБКА_ступени_без_слайса_пул_кончился`');
PREPARE `ap_check` FROM @check;
EXECUTE `ap_check`;
DEALLOCATE PREPARE `ap_check`;

DROP TEMPORARY TABLE IF EXISTS `ap_slice`;
CREATE TEMPORARY TABLE `ap_slice` (
  `lo`       INT UNSIGNED PRIMARY KEY,
  `class`    TINYINT UNSIGNED NOT NULL,
  `subclass` TINYINT UNSIGNED NOT NULL,
  `sound`    INT NOT NULL,
  `invtype`  TINYINT UNSIGNED NOT NULL,
  `material` TINYINT NOT NULL,
  `sheath`   TINYINT UNSIGNED NOT NULL,
  `display`  INT UNSIGNED NOT NULL
);

INSERT INTO `ap_slice`
SELECT r.`pool_lo`, b.`class`, b.`subclass`, b.`SoundOverrideSubclass`,
       b.`InventoryType`, b.`Material`, b.`Sheath`, b.`displayid`
FROM `ap_recipe_result` r
JOIN `ap_need` q ON q.`recipe_id` = r.`recipe_id` AND q.`quality` = r.`quality`
JOIN `item_template` b ON b.`entry` = r.`result_entry`;

SET SESSION cte_max_recursion_depth = 1000;

DROP TEMPORARY TABLE IF EXISTS `ap_seq`;
CREATE TEMPORARY TABLE `ap_seq` (`n` INT UNSIGNED PRIMARY KEY);
INSERT INTO `ap_seq`
WITH RECURSIVE `seq` (`n`) AS (
  SELECT 0 UNION ALL SELECT `n` + 1 FROM `seq` WHERE `n` < @seed - 1
)
SELECT `n` FROM `seq`;

INSERT IGNORE INTO `item_template`
  (`entry`, `class`, `subclass`, `SoundOverrideSubclass`, `name`, `displayid`,
   `Quality`, `Flags`, `InventoryType`, `Stackable`, `MaxCount`, `Material`,
   `Sheath`)
SELECT s.`lo` + q.`n`, s.`class`, s.`subclass`, s.`sound`,
       CONCAT('[заготовка верстака ', s.`lo` + q.`n`, ']'),
       s.`display`, 0, 16, s.`invtype`, 1, 0, s.`material`, s.`sheath`
FROM `ap_slice` s JOIN `ap_seq` q;

DROP TEMPORARY TABLE IF EXISTS `ap_slice`;
DROP TEMPORARY TABLE IF EXISTS `ap_seq`;
DROP TEMPORARY TABLE IF EXISTS `ap_free`;
DROP TEMPORARY TABLE IF EXISTS `ap_need`;
DROP TEMPORARY TABLE IF EXISTS `ap_cellseq`;
DROP TEMPORARY TABLE IF EXISTS `ap_hero`;

-- Каталог меняется: у верстака прибавилось основ и эскизов (§7).
UPDATE `ap_config` SET `value` = `value` + 1 WHERE `name` = 'catalog_version';
